function saveSVG(file_name) {
	let grStr = "";
	for (let i = 0; i < objs.length; i++) { // for (const gr of svgGr) {
		const o = objs[i];
		grStr += `<g id="${color2Hex(o.clr)}-${i}"  stroke="${color2Hex(o.clr)}" fill="none">\n`;
		grStr += o.poly.toSVG();
		grStr += `</g>\n`;
	}

	grStr += `<g id="lines" stroke="grey" fill="none">\n`;
	grStr += bgLinesPoly.toSVG();
	grStr += `</g>\n`;

	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n${grStr}\n</svg>`;
	// console.log(svgStr);
	save(svgStr.split("\n"), file_name);
}

