const { Point, Line, Polygon } = EpiShapeSvg; // external library https://cdn.jsdelivr.net/gh/epibyte/p5-epi-shapesvg@v0.0.8/dist/p5-epi-shapesvg.js

const USE_SVG = true, SVG_SCL = 3;
let seed, pal, BG, S, MIN_NUM = 15;
let objs, num;

function setup() {
	createCanvas(USE_SVG ? 297 * SVG_SCL : windowWidth, USE_SVG ? 210 * SVG_SCL : windowHeight);
	describe("growing abstract forms slightly changing position, size and color forming trail");
	// drawingContext.globalCompositeOperation = "destination-over";
	frameRate(30);
	stroke(240);
	noFill();
	S = ~~min(width/MIN_NUM, height/MIN_NUM);

	seed = ~~random(987654321); // 329330205
	console.log(`seed: ${seed}`);
	noiseSeed(seed);
	randomSeed(seed);

	pal = [...random(palettes)];
	BG = adjColorBrightness(adjColorSaturation(random(pal), 1.5), 0.5);
	if (USE_SVG) BG = color(240);
	background(BG);

	objs = [];
	num = ~~(Math.sqrt(width+height)/2);
	for (let i = 0; i < num; i++) {
		var x = width * random(0.2, 0.8); // randomGaussian(width/2, 100);
		var y = randomGaussian(height/2, 100); // height * random(0.2, 0.8); // 
		insertObj(x, y);
	}
	// reverse order, so that small ones are still visible and not overlapped by big ones
	objs.sort((a, b) => b.max_sze - a.max_sze);
	if (USE_SVG) objs.reverse();

	drawBackground(BG);
	// drawTest();
}


function draw() {
	drawBackground(BG);
	let allreadyFinished = 0, newFinished = 0;

	const allObjsCombined = new Polygon();
	// pre merge all existing outer hulls
	for (const o of objs) {
		if (o.states.length) allObjsCombined.merge(o.states[o.states.length-1].hull);
	}

	for (const o of objs) {
		const justFinished = o.update(allObjsCombined);
		if (justFinished) {
			newFinished++;
		} else if (!o.growing) {
			allreadyFinished++;
		}
		allObjsCombined.merge(o.states[o.states.length-1].hull); // merge with new outer hull
	}

	// trigger to generate finished svg
	if (newFinished && newFinished + allreadyFinished === num) {
		drawBackgroundSvg();
		frameRate(5); // lower ressource usage
	}

}

function insertObj(x, y) {
	let ci1 = ~~random(pal.length);
	let ci2 = ci1;
	// ensure different colors
	if (pal.length > 1) while(ci2 === ci1) {
		ci2 = ~~random(pal.length)
	}
	objs.push(new VisualObj(x, y, S*random(0.65, 1.75), color(pal[ci1]), color(pal[ci2]))); // color(random(pal)), color(random(pal))
}


