function drawBackground(bg) {
	if (USE_SVG) return; // return drawBackgroundSvg(bg);

	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)/1000, 
		width/2, height/2, max(width, height)*0.65
	);
	gradient.addColorStop(0.3, bg);
	gradient.addColorStop(1, color(0, 16));

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);

	stroke(0, 50)
	strokeWeight(1.25)
	for (let y = 3; y < height; y += 4) {
		line(0, y, width, y)
	}

	pop()
}

function drawBackgroundSvg() {
	background(BG);
	noFill();
	stroke(128);

	allPrevObjsCombined = new Polygon();
	// merge all existing outer hulls
	for (const o of objs) {
		stroke(o.clr)
		let clippedObj = o.states[o.states.length-1].clipped; // all polygons of this obj without overlapping
		o.poly = clippedObj.clipTo(allPrevObjsCombined, false); // clip, that previous objects are in foreground
		o.poly.drawShape();
		if (o.states.length) allPrevObjsCombined.merge(o.states[o.states.length-1].hull); // merge for next obj
	}

	const d = height/20;
	const linesPoly = new Polygon();
	for (let y=d/2; y<height; y+=random(0.8, 1.2) * d) {
		const ln = new Line(new Point(0, y), new Point(width, y));
		linesPoly.addPtsArr([new Point(0, y), new Point(width, y)]);
	}
	bgLinesPoly = linesPoly.clipTo(allPrevObjsCombined, false);
	stroke(128);
	bgLinesPoly.drawShape();
}
